-- Reference schema 2. Onboarding creates these tables automatically. Do not import before setup.
CREATE TABLE meta (name VARCHAR(100) PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, username VARCHAR(150) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL);
CREATE TABLE tokens (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id BIGINT NOT NULL, hash VARCHAR(64) NOT NULL UNIQUE, label VARCHAR(150) NOT NULL, expires VARCHAR(30) NOT NULL, revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE records (id INTEGER PRIMARY KEY AUTOINCREMENT, kind VARCHAR(40) NOT NULL, payload TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created VARCHAR(30) NOT NULL, updated VARCHAR(30) NOT NULL);
CREATE TABLE revisions (id INTEGER PRIMARY KEY AUTOINCREMENT, record_id BIGINT NOT NULL, user_id BIGINT NOT NULL, payload TEXT NOT NULL, action VARCHAR(40) NOT NULL, created VARCHAR(30) NOT NULL);
CREATE TABLE requests (request_key VARCHAR(100) PRIMARY KEY, user_id BIGINT NOT NULL, response TEXT NOT NULL, created VARCHAR(30) NOT NULL);
CREATE TABLE files (id INTEGER PRIMARY KEY AUTOINCREMENT, record_id BIGINT NOT NULL, user_id BIGINT NOT NULL, filename VARCHAR(100) NOT NULL, mime VARCHAR(40) NOT NULL, caption TEXT NOT NULL, view_label VARCHAR(40) NOT NULL, item_key VARCHAR(80), created VARCHAR(30) NOT NULL);
INSERT INTO meta(name,value) VALUES ('schema_version','2');
